
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_scan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_scan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.656286400092172e-02, -2.651927103809202e-02, -2.645495297840513e-02, -2.635905321924910e-02, -2.621401542284656e-02, -2.599068070171641e-02, -2.564040219235479e-02, -2.509097870413858e-02, -2.433429588737476e-02, -2.477999783050728e-02, -3.052133056807905e-02, -4.855213436163921e-02, -3.863400296314982e-02, -2.413884119230081e-02, -1.909665577896552e-02, -1.415136562800377e-02, -7.153490563487574e-03, -2.602052743157618e-03, -4.809691823191655e-04, -2.764914743464832e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


